(function initTectonicKinematics() {
    const H = 360, W = 720, D2R = Math.PI / 180.0, R2D = 180.0 / Math.PI, R_EARTH_KM = 6371.0;
    const grid = new Int16Array(H * W);
    let pos = 0;
    for (let i = 0; i < TECTONIC_GRID_RLE.length; i += 2) {
        const val = TECTONIC_GRID_RLE[i], len = TECTONIC_GRID_RLE[i + 1];
        grid.fill(val, pos, pos + len);
        pos += len;
    }

    function ll2vec(lat, lon) {
        const p = lat * D2R, l = lon * D2R, cp = Math.cos(p);
        return [cp * Math.cos(l), cp * Math.sin(l), Math.sin(p)];
    }

    function vec2ll(x, y, z) {
        const hyp = Math.hypot(x, y);
        return [Math.atan2(z, hyp) * R2D, Math.atan2(y, x) * R2D];
    }

    function getPlateIdxAt(lat, lon) {
        let la = Math.max(-89.9, Math.min(89.9, lat));
        let lo = ((lon + 180.0) % 360.0 + 360.0) % 360.0 - 180.0;
        let r = Math.min(H - 1, Math.max(0, Math.floor((la + 90.0) * 2)));
        let c = Math.floor((lo + 180.0) * 2) % W;
        return grid[r * W + c];
    }

    // Exact 3D Rodrigues rotation around plate's NNR-MORVEL56 Euler pole by `years` into future
    function rotateByPlate(lat, lon, plateIdx, years) {
        const meta = TECTONIC_PLATES_META[plateIdx];
        if (!meta || years === 0) return [lat, lon];
        const myr = years / 1e6;
        const wx = meta[4], wy = meta[5], wz = meta[6];
        const om = Math.hypot(wx, wy, wz);
        if (om < 1e-12) return [lat, lon];
        const theta = om * myr;
        const kx = wx / om, ky = wy / om, kz = wz / om;
        const v = ll2vec(lat, lon);
        const c = Math.cos(theta), s = Math.sin(theta), oneC = 1.0 - c;
        const kdotv = kx * v[0] + ky * v[1] + kz * v[2];
        const cx = ky * v[2] - kz * v[1];
        const cy = kz * v[0] - kx * v[2];
        const cz = kx * v[1] - ky * v[0];
        const rx = v[0] * c + cx * s + kx * kdotv * oneC;
        const ry = v[1] * c + cy * s + ky * kdotv * oneC;
        const rz = v[2] * c + cz * s + kz * kdotv * oneC;
        return vec2ll(rx, ry, rz);
    }

    // Current instantaneous plate velocity (mm/yr, azimuth deg, east/north components)
    function getVelocityAt(lat, lon, forcedPlateIdx) {
        const pidx = (forcedPlateIdx !== undefined && forcedPlateIdx >= 0) ? forcedPlateIdx : getPlateIdxAt(lat, lon);
        const meta = TECTONIC_PLATES_META[pidx];
        if (!meta) return { plate: 'Unknown', speedMmYr: 0, azDeg: 0, ve: 0, vn: 0 };
        const p = lat * D2R, l = lon * D2R;
        const v = ll2vec(lat, lon);
        // omega is in rad/Myr -> v_mm_yr = (omega / 1e6) * R_m * 1000 = omega * 6371.0
        const wx = meta[4], wy = meta[5], wz = meta[6];
        const vx = (wy * v[2] - wz * v[1]) * R_EARTH_KM;
        const vy = (wz * v[0] - wx * v[2]) * R_EARTH_KM;
        const vz = (wx * v[1] - wy * v[0]) * R_EARTH_KM;
        const eastX = -Math.sin(l), eastY = Math.cos(l);
        const northX = -Math.sin(p) * Math.cos(l), northY = -Math.sin(p) * Math.sin(l), northZ = Math.cos(p);
        const ve = vx * eastX + vy * eastY;
        const vn = vx * northX + vy * northY + vz * northZ;
        const speed = Math.hypot(ve, vn);
        const az = (Math.atan2(ve, vn) * R2D + 360.0) % 360.0;
        return { plate: meta[0], plateIdx: pidx, speedMmYr: speed, azDeg: az, ve: ve, vn: vn };
    }

    window.TectonicModel = {
        plates: TECTONIC_PLATES_META,
        segMeta: TECTONIC_SEG_META,
        getPlateIdxAt: getPlateIdxAt,
        getPlateName: (idx) => (TECTONIC_PLATES_META[idx] ? TECTONIC_PLATES_META[idx][0] : 'Unknown'),
        rotateByPlate: rotateByPlate,
        getVelocityAt: getVelocityAt,
        ll2vec: ll2vec,
        vec2ll: vec2ll
    };
})();
